<?php require_once __DIR__.'/../includes/functions.php';need_role(['admin_utama']);if($_SERVER['REQUEST_METHOD']!=='POST')go('/laporwarga/admin-utama/kategori.php');check_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id_kategori']??0);if($action==='toggle'){db()->prepare('UPDATE categories SET status_kategori=IF(status_kategori=1,0,1) WHERE id_kategori=?')->execute([$id]);log_activity('ubah_status_kategori','id='.$id);flash('success','Status kategori diperbarui.');go('/laporwarga/admin-utama/kategori.php');}$name=trim($_POST['nama_kategori']??'');$desc=trim($_POST['deskripsi']??'');if($name===''){flash('error','Nama kategori wajib diisi.');go('/laporwarga/admin-utama/kategori.php');}try{if($id)db()->prepare('UPDATE categories SET nama_kategori=?,deskripsi=? WHERE id_kategori=?')->execute([$name,$desc,$id]);else db()->prepare('INSERT INTO categories(nama_kategori,deskripsi) VALUES(?,?)')->execute([$name,$desc]);log_activity('simpan_kategori',$name);flash('success','Kategori berhasil disimpan.');}catch(Throwable $e){flash('error','Kategori gagal disimpan. Pastikan nama belum digunakan.');}go('/laporwarga/admin-utama/kategori.php');